export type Category = "Lingerie" | "Swim" | "Jewelry" | "Collection";

export interface Product {
  slug: string;
  name: string;
  price: number;
  compareAt?: number;
  category: Category;
  bundle?: boolean;
  description: string;
  details: string[];
  materials: string;
  sizes: string[] | null;
  /** Label above the selector — "Size" for apparel/rings, "Finish" for metals. */
  sizeLabel?: string;
  images: string[];
}

// Auto-generated by scripts/scan-images.mjs — lists whatever images you've
// dropped into public/products/<color>/. Drop any-named files there; the
// scan runs before every `npm run dev` / build. Falls back to the flat
// filenames below if a folder is empty.
import scanned from "./product-images.json";

const imagesFor = (slug: string, fallback: string[]) => {
  const found = (scanned as Record<string, string[]>)[slug];
  return found && found.length ? found : fallback;
};

