/* the shoppable four, campaign order — grids, rails, and related lists use this */
export const catalog = products.filter((p) => !p.bundle);

export const bundleProduct = products.find((p) => p.bundle)!;

export const bundleSavings =
  (bundleProduct.compareAt ?? 0) - bundleProduct.price;

export const getProduct = (slug: string) =>
  products.find((p) => p.slug === slug);

export const formatPrice = (n: number) => `$${n.toLocaleString("en-US")}`;
